# WINDY
# ============================================================

WINDY_CENTER_LAT = MAP_CENTER_LAT
WINDY_CENTER_LON = MAP_CENTER_LON
WINDY_ZOOM = 5


def construir_windy_url(
    overlay="wind"
):

    parametros = {
        "type": "map",
        "location": "coordinates",
        "metricRain": "default",
        "metricTemp": "default",
        "metricWind": "default",
        "zoom": WINDY_ZOOM,
        "overlay": overlay,
        "product": "ecmwf",
        "level": "surface",
        "lat": WINDY_CENTER_LAT,
        "lon": WINDY_CENTER_LON,
    }

    return (
        "https://embed.windy.com/embed.html?"
        + urlencode(parametros)
    )


def mostrar_windy(
    overlay="wind"
):

    windy_url = construir_windy_url(
        overlay
    )

    iframe = f'''
    <iframe
        width="100%"
        height="700"
        src="{html.escape(windy_url, quote=True)}"
        frameborder="0"
        style="border:0; border-radius:10px;"
        title="Windy — pronóstico meteorológico del Litoral"
        allowfullscreen>
    </iframe>
    '''

    components.html(
        iframe,
        height=720,
        scrolling=False,
    )


