# ============================================================
# PRONÓSTICO EXTENDIDO
# ============================================================

def extraer_pronostico_diario(
    datos
):

    daily = (
        datos or {}
    ).get(
        "daily",
        {}
    ) or {}

    fechas = daily.get(
        "time",
        []
    )

    if not fechas:
        return pd.DataFrame()

    def arr(nombre):

        valores = daily.get(
            nombre,
            []
        )

        salida = list(valores)[
            :len(fechas)
        ]

        if len(salida) < len(fechas):

            salida += [
                np.nan
            ] * (
                len(fechas)
                - len(salida)
            )

        return salida

    tabla = pd.DataFrame({

        "Fecha":
            pd.to_datetime(
                fechas,
                errors="coerce",
            ),

        "Tiempo":
            arr("weather_code"),

        "Temp. mínima":
            arr("temperature_2m_min"),

        "Temp. máxima":
            arr("temperature_2m_max"),

        "Sensación mínima":
            arr("apparent_temperature_min"),

        "Sensación máxima":
            arr("apparent_temperature_max"),

        "Precipitación":
            arr("precipitation_sum"),

        "Lluvia":
            arr("rain_sum"),

        "Chaparrones":
            arr("showers_sum"),

        "Prob. precipitación":
            arr(
                "precipitation_probability_max"
            ),

        "Horas con precipitación":
            arr("precipitation_hours"),

        "Viento máximo":
            arr("wind_speed_10m_max"),

        "Ráfaga máxima":
            arr("wind_gusts_10m_max"),

        "Dirección viento":
            arr(
                "wind_direction_10m_dominant"
            ),

        "CAPE máximo":
            arr("cape_max"),

        "Radiación solar":
            arr(
                "shortwave_radiation_sum"
            ),

        "Horas de sol":
            arr("sunshine_duration"),

        "ET₀":
            arr(
                "et0_fao_evapotranspiration"
            ),
    })

    tabla["Tiempo"] = tabla[
        "Tiempo"
    ].apply(
        lambda x:
            descripcion_wmo(x)
            if pd.notna(x)
            else "Sin dato"
    )

    tabla[
        "Dirección viento"
    ] = tabla[
        "Dirección viento"
    ].apply(
        lambda x:
            f"{float(x):.0f}° "
            f"{direccion_compass(x)}"
            if pd.notna(x)
            else "Sin dato"
    )

    tabla[
        "Horas de sol"
    ] = (
        tabla["Horas de sol"]
        / 3600.0
    )

    fecha_hoy = pd.Timestamp(
        ahora().date()
    )

    tabla = tabla[
        tabla["Fecha"] >= fecha_hoy
    ].copy()

    return (
        tabla
        .dropna(subset=["Fecha"])
        .head(15)
        .reset_index(drop=True)
    )


