# Respaldo incluido para que la cabecera funcione aun si se sube solo app.py.
HERO_TORMENTA_FALLBACK_B64 = ""

@st.cache_data(ttl=86400, show_spinner=False)
def cargar_banner_tormenta():
    'Carga el fondo local de la cabecera sin incrustarlo en el código.'
    archivo_modulo = globals().get("__file__", str(Path.cwd() / "app.py"))
    archivo = Path(archivo_modulo).resolve().parent / "assets" / "tormenta_litoral_hero.jpg"
    try:
        if archivo.is_file():
            return "data:image/jpeg;base64," + base64.b64encode(archivo.read_bytes()).decode("ascii")
    except OSError:
        pass
    return "data:image/jpeg;base64," + HERO_TORMENTA_FALLBACK_B64


# Logo original incorporado: funciona también al subir únicamente app.py.
# assets/ala_logo.png permite reemplazarlo en futuras versiones.
ALA_LOGO_FALLBACK_B64 = ""


@st.cache_data(ttl=86400, show_spinner=False)
def cargar_logo_ala():
    archivo_modulo = globals().get("__file__", str(Path.cwd() / "app.py"))
    archivo = Path(archivo_modulo).resolve().parent / "assets" / "ala_logo.png"
    try:
        if archivo.is_file():
            return "data:image/png;base64," + base64.b64encode(archivo.read_bytes()).decode("ascii")
    except OSError:
        pass
    return "data:image/png;base64," + ALA_LOGO_FALLBACK_B64


